function Badge({value,lang='ru'}:{value:any,lang?:string}){const s=String(value||'UNKNOWN');const color=s==='QUALIFIED'||s==='DONE'||s==='success'||s==='COMPLETE'||s==='MERGED'?'green':s==='CRITICAL'||s==='BLOCKED'||s==='failure'?'red':/WARNING|PARTIAL|REQUIRED|PENDING|STALE|UNKNOWN|UNASSESSED|OPEN/.test(s)?'amber':'neutral';return <span title={s} className={`badge ${color}`}>{labelMap[s]?labelMap[s][lang==='ru'?0:1]:s}</span>}
