 const events=useMemo(()=>{const by=new Map<string,any>(seed.events.map((e:any)=>[e.id,{...e,origin:'main',sha:seed.sha}]));for(const im of state.imports.filter(i=>i.kind==='registry'))for(const e of im.data.events)by.set(e.id,{...e,origin:t('Ручной импорт','Manual import'),importedAt:im.importedAt});return [...by.values()]},[state.imports,lang]);
 const history=useMemo(()=>[...seed.history,...state.imports.filter(i=>i.kind==='calculation').map(i=>({...calcRow(i.data),id:i.id,path:i.name,origin:'MANUAL_IMPORT',review_status:'UNVERIFIED_IMPORT'}))].sort((a:any,b:any)=>Date.parse(a.as_of)-Date.parse(b.as_of)),[state.imports]);
 const latest=history.at(-1)||{as_of:'',result:{core_coverage_pct:null,core_factors:{}},snapshot:{}}, reports=[...seed.reports,...state.reports], checks=state.checks;
 function decision(e:any){return e.reviews?.at(-1)?.decision||'UNKNOWN'}
 function publication(e:any){return e.first_public_at||e.reviews?.toReversed().find((r:any)=>r.first_public_at_verified)?.first_public_at_verified||e.known_public_by_at||''}
 function matches(item:any,dt:string,st:string,ent:string){if(q&&!JSON.stringify(item).toLowerCase().includes(q.toLowerCase()))return false;if(company!=='all'&&!ent.toLowerCase().includes(company.toLowerCase()))return false;if(status!=='all'&&!st.split('|').includes(status))return false;if(!dt)return period==='all';const d=datePart(dt);if(period==='custom')return(!from||d>=from)&&(!to||d<=to);if(period==='all')return true;const cutoff=new Date();cutoff.setUTCDate(cutoff.getUTCDate()-(period==='7'?7:30));return d>=datePart(cutoff.toISOString())&&d<=datePart(now())}
 const visibleEvents=events.filter(e=>matches(e,basis==='published'?publication(e):e.event_date,decision(e)+'|'+(state.overlays[e.id]?.status||''),e.entity||'')).sort((a,b)=>b.event_date.localeCompare(a.event_date));
 const visibleReports=reports.filter(r=>r.type===tab&&matches(r,r.date,state.overlays[r.id]?.status||r.status,(r.ledger?.event_ids||[]).map((id:string)=>events.find(e=>e.id===id)?.entity||'').join(' ')||((r.type==='weekly')?'Microsoft Alphabet Google Amazon Meta Oracle CoreWeave':'') )).sort((a,b)=>b.date.localeCompare(a.date));
