 function open(kind:string,item:any){setModal({kind,item});if(kind==='check')setForm({...item});else if(kind==='newcheck')setForm({id:uid(),title:'',status:'OPEN',context:'',nextAction:'',owner:'',due:'',links:'',updatedAt:now()});else if(kind==='newreport')setForm({date:datePart(now()),type:tab==='weekly'?'weekly':'daily',path:'',status:'DRAFT'});else if(kind==='newcalendar')setForm({date:day||`${month}-11`,title:'',entity:'',priority:'HIGH',url:'',kind:'PLANNED',time:''});else setForm(state.overlays[item.id]||initialOverlay());}
 function close(){setModal(null)}
 async function saveModal(){if(!modal)return;let next={...state};const {kind,item}=modal;
 if(kind==='check'||kind==='newcheck'){if(kind==='newcheck'&&checks.some(c=>c.title.trim().toLowerCase()===form.title.trim().toLowerCase())){setError(t('Такая проверка уже есть — продолжите её','This check already exists — resume it'));return}if(!form.title.trim()){setError(t('Нужно название проверки','Check title required'));return}next.checks=kind==='check'?state.checks.map(c=>c.id===form.id?{...form,updatedAt:now()}:c):[...state.checks,{...form,updatedAt:now()}];}
 else if(kind==='newreport'){if(!/^\d{4}-\d{2}-\d{2}$/.test(form.date))return;const id=`${form.type}-${form.date}`;if(reports.some(r=>r.type===form.type&&r.date===form.date)){setError(t('Отчёт за этот период уже существует. Откройте его и продолжите.','A report for this period already exists. Open it to continue.'));return}next.reports=[...state.reports,{...form,id,sha:''}];next.checklist={...state.checklist,[id]:[]};}
 else if(kind==='newcalendar'){if(!form.title.trim()||!form.entity.trim()||!form.date){setError(t('Заполните дату, компанию и название','Date, entity and title required'));return}if(form.url&&!safeUrl(form.url)){setError('HTTPS URL required');return}const dup=state.calendar.some(c=>c.date===form.date&&c.entity===form.entity&&c.title===form.title);if(dup){setError(t('Такое событие уже добавлено','This calendar item already exists'));return}next.calendar=[...state.calendar,{...form,id:'CAL-'+uid()}];}
 else {if(form.pr&&!/^https:\/\/github\.com\/HelsingN\/AI_CapEx_Reversal\/pull\/\d+$/.test(form.pr)){setError(t('Нужна ссылка на PR в AI_CapEx_Reversal','Use a PR URL in AI_CapEx_Reversal'));return}
 if(kind==='report'&&form.status==='COMPLETE'&&!reportReady(state.checklist[item.id]||[],form.status)){setError(t('COMPLETE требует все 10 контрольных пунктов','COMPLETE requires all 10 checkpoints'));return}
 if(kind==='event'&&(!form.notes.trim()||!form.owner.trim())){setError(t('Укажите проверяющего и обоснование ручного решения','Reviewer and decision rationale are required'));return}
 next.overlays={...state.overlays,[item.id]:{...form,updatedAt:now()}};
 if(kind==='event'){const prior=state.reviews.filter(r=>r.target===item.id).at(-1)?.decision||decision(item);const needs=form.status==='QUALIFIED'||prior==='QUALIFIED'?'REQUIRED':form.recalc;next.overlays[item.id].recalc=needs;next.reviews=[...state.reviews,{id:uid(),target:item.id,decision:form.status,reason:form.notes,reviewedAt:now(),reviewer:form.owner,recalc:needs,source:form.pr}];}}
 change(next);close();await persist(next,`${kind}: ${item?.id||form.title||form.date}`)}
 function download(name:string,text:string,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
