 function exportEvents(){const rows=[['id','entity','title','event_date','publication','precision','priority','initial','final','factor','manual_status','recalc','source'],...visibleEvents.map(e=>[e.id,e.entity,e.title,e.event_date,publication(e),e.source_precision,e.priority,e.reviews?.[0]?.decision,decision(e),e.reviews?.at(-1)?.factor,state.overlays[e.id]?.status||'',state.overlays[e.id]?.recalc||'',e.reviews?.at(-1)?.evidence_refs?.join(' ')||e.source_refs?.join(' ')])];const esc=(v:any)=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};download('ai-capex-events.csv','\uFEFF'+rows.map(r=>r.map(esc).join(',')).join('\n'),'text/csv;charset=utf-8')}
 async function importFile(file:File){setImporting(true);setError('');try{if(file.size>2_500_000)throw Error('Import limit: 2.5 MB');const b=JSON.parse(await file.text());let next={...state};
 if(b.schema==='capex-desk.export.v1'){const incoming=WorkspaceSchema.parse(b.state);const merge=(a:any[],b:any[])=>{const m=new Map(a.map(x=>[x.id,x]));for(const x of b)if(!m.has(x.id))m.set(x.id,x);return [...m.values()]};next={...state,checks:merge(state.checks,incoming.checks),reports:merge(state.reports,incoming.reports),calendar:merge(state.calendar,incoming.calendar),imports:merge(state.imports,incoming.imports),reviews:merge(state.reviews,incoming.reviews),overlays:{...incoming.overlays,...state.overlays},checklist:{...incoming.checklist,...state.checklist}};}
 else if(Array.isArray(b.events)){if(b.events.length>1000)throw Error('Registry import limit: 1,000 events');for(const e of b.events){if(!/^EVT-\d{8}-[A-F0-9]{12}$/.test(e.id)||!e.event_key||!Array.isArray(e.reviews)||!e.reviews.length||!['HIGH','CRITICAL'].includes(e.priority)||!e.event_date||!e.entity||!e.title)throw Error('Invalid canonical event record');const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(e.event_key.toUpperCase()));const hash=[...new Uint8Array(bytes)].map(x=>x.toString(16).padStart(2,'0')).join('').slice(0,12).toUpperCase();if(e.id!==`EVT-${e.event_date.replaceAll('-','')}-${hash}`)throw Error('Event identity does not match canonical key');const old=events.find(v=>v.id===e.id||v.event_key.toUpperCase()===e.event_key.toUpperCase());if(old){if(old.id!==e.id||old.event_date!==e.event_date||e.reviews.length<old.reviews.length||old.reviews.some((r:any,i:number)=>JSON.stringify(r)!==JSON.stringify(e.reviews[i])))throw Error('Import would rewrite identity or existing reviews');}}
 const changed=b.events.filter((e:any)=>!events.some(v=>v.id===e.id&&JSON.stringify(v.reviews)===JSON.stringify(e.reviews)));if(!changed.length){setNotice(t('Дубликатов не добавлено: все события уже есть','No duplicates added: all events already exist'));return}next.imports=[...state.imports,{id:uid(),name:file.name,importedAt:now(),kind:'registry',data:{events:changed}}];}
 else {const row=calcRow(b);if(history.some((h:any)=>h.as_of===row.as_of&&JSON.stringify(h.result)===JSON.stringify(row.result))){setNotice(t('Этот расчёт уже сохранён','This calculation is already saved'));return}next.imports=[...state.imports,{id:uid(),name:file.name,importedAt:now(),kind:'calculation',data:b}];}
 change(next);await persist(next,`Import: ${file.name}`);}
 catch(e){setError((e as Error).message)}finally{setImporting(false);if(upload.current)upload.current.value=''}}
 const reset=()=>{setQ('');setCompany('all');setStatus('all');setPeriod('all');setFrom('');setTo('')};
