 function restoreDraft(){try{const d=JSON.parse(localStorage.getItem('capex-unsaved')||'null');if(!d)throw Error(t('Нет несохранённого черновика','No unsaved draft'));if(d.revision!==revision)throw Error(t('Ревизии отличаются. Экспортируйте черновик перед восстановлением.','Revisions differ. Export the draft before restoring.'));change(WorkspaceSchema.parse(d.state));setNotice(t('Черновик восстановлен; нажмите «Сохранить»','Draft restored; click Save'));}catch(e){setError((e as Error).message)}}
